def can_split_sequence(n, a):
    if n == 1:
        return "YES", [0]

    # Initialize the result array
    res = [-1] * n

    # Try to assign each element to either increasing or decreasing
    for i in range(n):
        if res[i] == -1:
            # Start a new increasing sequence
            res[i] = 0
            for j in range(i + 1, n):
                if a[j] > a[j - 1]:
                    res[j] = 0
                else:
                    break

            # Start a new decreasing sequence
            res[i] = 1
            for j in range(i + 1, n):
                if a[j] < a[j - 1]:
                    res[j] = 1
                else:
                    break

    # Check if the assignment is valid
    increasing = []
    decreasing = []

    for i in range(n):
        if res[i] == 0:
            if increasing and a[i] <= increasing[-1]:
                return "NO", []
            increasing.append(a[i])
        else:
            if decreasing and a[i] >= decreasing[-1]:
                return "NO", []
            decreasing.append(a[i])

    return "YES", res

